// the optional cloud code importable without adding an account or secret.
const local = isLocalMode();
const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL || (local ? 'http://127.0.0.1:54321' : '');
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || (local ? 'local-mode-not-used' : '');

// Import the supabase client like this:
